class Solution:
    def myAtoi(self, s: str) -> int:
        i, n = 0, len(s)
        while i < n and s[i] == ' ':
            i += 1
        if i == n:
            return 0
        sign = 1
        if s[i] in '+-':
            sign = -1 if s[i] == '-' else 1
            i += 1
        val = 0
        lo, hi = -(1 << 31), (1 << 31) - 1
        while i < n and s[i].isdigit():
            val = val * 10 + int(s[i])
            i += 1
        return max(lo, min(hi, sign * val))

