from collections import Counter

class Solution:
    def findSubstring(self, s: str, words: list[str]) -> list[int]:
        if not s or not words:
            return []
        w = len(words[0])
        total = len(words)
        need = Counter(words)
        out = []
        for offset in range(w):
            left = offset
            seen = Counter()
            matched = 0
            for right in range(offset, len(s) - w + 1, w):
                word = s[right:right + w]
                if word in need:
                    seen[word] += 1
                    matched += 1
                    while seen[word] > need[word]:
                        lw = s[left:left + w]
                        seen[lw] -= 1
                        matched -= 1
                        left += w
                    if matched == total:
                        out.append(left)
                else:
                    seen.clear()
                    matched = 0
                    left = right + w
        return out

