class Solution:
    def searchRange(self, nums: list[int], target: int) -> list[int]:
        def bound(first: bool) -> int:
            lo, hi, ans = 0, len(nums) - 1, -1
            while lo <= hi:
                mid = (lo + hi) // 2
                if nums[mid] == target:
                    ans = mid
                    if first:
                        hi = mid - 1
                    else:
                        lo = mid + 1
                elif nums[mid] < target:
                    lo = mid + 1
                else:
                    hi = mid - 1
            return ans
        return [bound(True), bound(False)]

