class Solution:
    def fullJustify(self, words: list[str], maxWidth: int) -> list[str]:
        res, line, chars = [], [], 0
        for w in words:
            if line and chars + len(w) + len(line) > maxWidth:
                spaces = maxWidth - chars
                if len(line) == 1:
                    res.append(line[0] + ' ' * spaces)
                else:
                    q, r = divmod(spaces, len(line) - 1)
                    parts = []
                    for idx, word in enumerate(line[:-1]):
                        parts.append(word + ' ' * (q + (1 if idx < r else 0)))
                    parts.append(line[-1])
                    res.append(''.join(parts))
                line, chars = [], 0
            line.append(w)
            chars += len(w)
        last = ' '.join(line)
        res.append(last + ' ' * (maxWidth - len(last)))
        return res

