        pos = {v: i for i, v in enumerate(inorder)}
        idx = len(postorder) - 1
        def build(lo: int, hi: int) -> Optional[TreeNode]:
            nonlocal idx
            if lo > hi:
                return None
            val = postorder[idx]
            idx -= 1
            node = TreeNode(val)
            mid = pos[val]
            node.right = build(mid + 1, hi)
            node.left = build(lo, mid - 1)
            return node
        return build(0, len(inorder) - 1)

