class Solution:
    def minSubArrayLen(self, target: int, nums: list[int]) -> int:
        left = 0
        cur = 0
        best = len(nums) + 1
        for right, x in enumerate(nums):
            cur += x
            while cur >= target:
                best = min(best, right - left + 1)
                cur -= nums[left]
                left += 1
        return 0 if best > len(nums) else best

