class Solution:
    def longestPalindrome(self, s: str) -> int:
        odd_seen = False
        ans = 0
        for cnt in Counter(s).values():
            ans += (cnt // 2) * 2
            if cnt % 2 == 1:
                odd_seen = True
        return ans + (1 if odd_seen else 0)

