class Solution:
    def findAnagrams(self, s: str, p: str) -> list[int]:
        m, n = len(p), len(s)
        if m > n:
            return []
        need = [0] * 26
        win = [0] * 26
        base = ord('a')
        for ch in p:
            need[ord(ch) - base] += 1
        out = []
        for i, ch in enumerate(s):
            win[ord(ch) - base] += 1
            if i >= m:
                win[ord(s[i - m]) - base] -= 1
            if win == need:
                out.append(i - m + 1)
        return out

