class Solution:
    def averageOfLevels(self, root: Optional[TreeNode]) -> list[float]:
        if not root:
            return []
        q = deque([root])
        out = []
        while q:
            k = len(q)
            total = 0
            for _ in range(k):
                node = q.popleft()
                total += node.val
                if node.left:
                    q.append(node.left)
                if node.right:
                    q.append(node.right)
            out.append(total / k)
        return out

