from collections import deque

class Solution:
    def snakesAndLadders(self, board: list[list[int]]) -> int:
        n = len(board)
        target = n * n
        def cell(s: int) -> int:
            r_from_bot, col = divmod(s - 1, n)
            r = n - 1 - r_from_bot
            if r_from_bot % 2 == 1:
                col = n - 1 - col
            return board[r][col]
        q = deque([(1, 0)])
        seen = {1}
        while q:
            sq, moves = q.popleft()
            for step in range(1, 7):
                nxt = sq + step
                if nxt > target:
                    break
                dest = cell(nxt)
                if dest != -1:
                    nxt = dest
                if nxt == target:
                    return moves + 1
                if nxt not in seen:
                    seen.add(nxt)
                    q.append((nxt, moves + 1))
        return -1

