import bisect

class Solution:
    def jobScheduling(self, startTime: list[int], endTime: list[int], profit: list[int]) -> int:
        jobs = sorted(zip(endTime, startTime, profit))
        ends = [0]
        dp = [0]
        for e, s, p in jobs:
            idx = bisect.bisect_right(ends, s) - 1
            cand = dp[idx] + p
            if cand > dp[-1]:
                ends.append(e)
                dp.append(cand)
        return dp[-1]

